 'permission':{title:'Allow screen sharing',intro:'Miraya needs screen access to share the display, window or area you choose.',steps:['Open Screen & System Audio Recording in System Settings.','Turn on Miraya. Your microphone is never captured.','Quit and reopen Miraya if macOS asks, then check access.'],primary:'Open System Settings',action:'recording-settings',detail:'An enabled permission can belong to an older app signature. The help guide explains refreshing only Miraya’s entry.'},
 'local-network':{title:'Let Miraya find your TV',intro:'Discovery is unavailable. Local Network access may need your attention.',steps:['Check Miraya in System Settings → Privacy & Security → Local Network.','Open Miraya on the TV and use the same local network.','Refresh, or try the address shown on the TV.'],primary:'Open Network Settings',action:'network-settings',detail:'Discovery failure does not uniquely identify a permission problem. VPNs, guest-network isolation and a closed TV app can have similar symptoms.'},
 'network':{title:'Your TV hasn’t appeared',intro:'Miraya can’t tell whether the TV app is closed or the devices cannot reach each other.',steps:['Leave Miraya open on the TV.','Check the same home network; a guest network may block local devices.','Try Refresh or enter the TV’s address.'],primary:'Refresh TVs',action:'refresh',detail:'No Wi-Fi signal strength or distance from the router is measured.'},
 'refused':{title:'The TV isn’t accepting a connection',intro:'Open Miraya on Living Room TV, then try again.',steps:['Check the app is on its ready screen.','If using an address, verify the port shown by the TV.'],primary:'Try again',action:'share',detail:'A refused connection can mean the app is closed or the address/port is wrong.'},
 'rejected':{title:'The TV declined this connection',intro:'Nothing was shared. Start again only when you are ready to approve with the TV remote.',steps:[],primary:'Back to sharing',action:'ready',detail:'A TV denial is final for this attempt. Miraya does not automatically retry a denial.'},
 'mismatch':{title:'The numbers don’t match',intro:'Cancel this attempt. Nothing was shared and no new trust was saved.',steps:['Check you chose the intended TV.','Start again to compare a fresh six-digit code.'],primary:'Try pairing again',action:'new-pair',detail:'Matching digits and explicit TV approval are both required.'},
 'expired':{title:'That pairing has expired',intro:'Start a fresh attempt and compare the new numbers on both screens.',steps:[],primary:'Get a new code',action:'new-pair',detail:'The comparison window is 90 seconds. TV remote approval has its own 30-second deadline.'},
 'trust-invalid':{title:'This TV’s identity has changed',intro:'Sharing is blocked until you verify what changed.',steps:['If you reset or reinstalled Miraya on the TV, remove this saved pairing.','Pair again and compare the new code on the actual TV.','If you did not expect a change, cancel and check the TV.'],primary:'Review saved pairing',action:'trusted',detail:'Miraya does not silently replace a saved certificate pin.'},
 'trust-revoked':{title:'This Mac is no longer trusted',intro:'The TV has removed its saved permission for this Mac.',steps:['Remove the old TV pairing on this Mac.','Connect again, compare the six digits and approve with the remote.'],primary:'Review saved pairing',action:'trusted',detail:'A saved device name or UUID is not authorization.'},
