 'format-error':{title:'This media couldn’t be played',intro:'Use a supported local file or a direct HTTPS media address.',steps:['Website pages, browser blob URLs and login sessions are not direct media.','Check the format is supported by your TV.','Use Share screen when you need browser extensions.'],primary:'Choose other media',action:'media-ready',detail:'Protected media also needs a service-authorized playback path. Miraya does not supply a DRM license or transfer browser cookies.'},
 'interrupted':{title:'The connection was interrupted',intro:'Your screen is no longer being sent. Check the TV app and local network.',steps:['Reopen Miraya on the TV if it closed.','Choose the same TV and reconnect.'],primary:'Reconnect',action:'share',detail:'Unexpected mirror disconnections may retry the same trusted TV up to three times. Direct movies do not automatically restart from the beginning.'},
 'reconnect-failed':{title:'Couldn’t reconnect to the TV',intro:'Miraya stopped after three attempts. Your screen is no longer being sent.',steps:['Check that Miraya is open on the TV.','Check the local network, then start a fresh connection.'],primary:'Try again',action:'share',detail:'Explicit Stop, Back, denial or user cancellation never resumes automatically.'},
