 'manual-failed':{title:'Couldn’t reach that address',intro:'Check the address and port shown in Connection details on your TV.',steps:['Leave Miraya open on the TV.','Use an IP address or hostname, without https:// or a path.'],primary:'Edit address',action:'manual',detail:'Manual entry bypasses discovery only. It cannot overcome a firewall or client isolation.'},
 'media-error':{title:'The video source is unavailable',intro:'The TV could not open this media. Your desktop was not shared.',steps:['Check that the HTTPS media URL is accessible.','Choose the local file again if it moved or changed.'],primary:'Choose media',action:'media-ready',detail:'An HTTP 403/404 or unsupported codec is not repaired by lowering the screen-mirroring quality preset.'}
